settings.custom_liquid:
{% comment %}
  Bestdeal.pk Animated Waves - paste this into a Shopify "Custom liquid" section.
  This is intentionally separate from the footer.
{% endcomment %}

<style>
  .bestdeal-custom-waves {
    --wave-purple: #6F2ED6;
    --wave-gold: #9A6A35;
    --wave-soft: #8D5B9A;
    position: relative;
    width: 100%;
    height: 130px;
    overflow: hidden;
    background: transparent;
    line-height: 0;
    pointer-events: none;
  }

  .bestdeal-custom-waves .bdcw-wave {
    position: absolute;
    left: -3%;
    bottom: 0;
    width: 106%;
    height: 100%;
    transform-origin: center bottom;
    will-change: transform;
  }

  .bestdeal-custom-waves .bdcw-wave--1 {
    opacity: .72;
    animation: bdcwWave1 5s ease-in-out infinite;
  }

  .bestdeal-custom-waves .bdcw-wave--2 {
    opacity: .50;
    animation: bdcwWave2 7s ease-in-out infinite;
  }

  .bestdeal-custom-waves .bdcw-wave--3 {
    opacity: .30;
    animation: bdcwWave3 9s ease-in-out infinite;
  }

  @keyframes bdcwWave1 {
    0%,100% { transform: translate3d(-1.2%,0,0) scaleX(1.02); }
    50% { transform: translate3d(1.3%,7px,0) scaleX(1.05); }
  }

  @keyframes bdcwWave2 {
    0%,100% { transform: translate3d(1%,4px,0) scaleX(1.05); }
    50% { transform: translate3d(-1.6%,-5px,0) scaleX(1.01); }
  }

  @keyframes bdcwWave3 {
    0%,100% { transform: translate3d(-.8%,-2px,0) scaleX(1.01); }
    50% { transform: translate3d(1.8%,9px,0) scaleX(1.06); }
  }

  @media screen and (max-width: 749px) {
    .bestdeal-custom-waves {
      height: 90px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .bestdeal-custom-waves .bdcw-wave {
      animation: none !important;
    }
  }
</style>

<div class="bestdeal-custom-waves" aria-hidden="true">
  <svg class="bdcw-wave bdcw-wave--1" viewBox="0 0 1440 180" preserveAspectRatio="none">
    <path fill="var(--wave-purple)" d="M-20 98 C 170 40, 350 145, 565 91 S 935 29, 1175 86 S 1415 132, 1490 72 L 1490 200 L -20 200 Z"/>
  </svg>

  <svg class="bdcw-wave bdcw-wave--2" viewBox="0 0 1440 180" preserveAspectRatio="none">
    <path fill="var(--wave-gold)" d="M-35 120 C 175 151, 350 45, 565 111 S 910 154, 1125 77 S 1385 35, 1490 93 L 1490 200 L -35 200 Z"/>
  </svg>

  <svg class="bdcw-wave bdcw-wave--3" viewBox="0 0 1440 180" preserveAspectRatio="none">
    <path fill="var(--wave-soft)" d="M-25 94 C 180 155, 370 74, 610 118 S 930 150, 1120 92 S 1360 70, 1490 118 L 1490 200 L -25 200 Z"/>
  </svg>
</div>
